import { useState } from "react";

const L = "#C8FF00";
const BG = "#0a0a0a";
const CARD = "#141414";
const SURF = "#0f0f0f";
const BR = "#1e1e1e";

/* ─── GLOBAL STYLES ─── */
const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:ital,wght@0,600;0,700;0,800;0,900;1,700;1,800;1,900&family=Barlow:wght@300;400;500;600&family=DM+Mono:wght@400;500&display=swap');
*{margin:0;padding:0;box-sizing:border-box;}
html{-webkit-text-size-adjust:100%;}
.tp{font-family:'Barlow',sans-serif;background:${BG};color:#f0f0f0;max-width:430px;margin:0 auto;min-height:100vh;position:relative;overflow-x:hidden;}
@media(min-width:431px){.tp{box-shadow:0 0 80px rgba(0,0,0,0.9);}}

/* NAV */
.tp-nav{position:sticky;top:0;z-index:300;background:rgba(10,10,10,0.97);backdrop-filter:blur(14px);border-bottom:1px solid ${BR};padding:0.8rem 1.2rem;display:flex;align-items:center;justify-content:space-between;}
.tp-nav-logo{display:flex;flex-direction:column;gap:1px;cursor:pointer;}
.tp-logo-main{font-family:'Barlow Condensed',sans-serif;font-weight:900;font-size:1.45rem;letter-spacing:0.05em;color:#fff;line-height:1;}
.tp-logo-main span{color:${L};}
.tp-logo-sub{font-family:'DM Mono',monospace;font-size:0.46rem;letter-spacing:0.22em;text-transform:uppercase;color:#444;}
.tp-ham{display:flex;flex-direction:column;gap:4px;cursor:pointer;padding:6px 4px;}
.tp-ham span{display:block;width:22px;height:1.5px;background:#888;transition:background 0.2s;}
.tp-ham:hover span{background:${L};}

/* SLIDE-OUT MENU */
.tp-menu-overlay{position:fixed;inset:0;background:rgba(0,0,0,0.65);z-index:400;opacity:0;pointer-events:none;transition:opacity 0.3s;}
.tp-menu-overlay.open{opacity:1;pointer-events:all;}
.tp-menu-drawer{position:fixed;top:0;right:-110%;width:82%;max-width:340px;height:100%;background:#111;border-left:1px solid ${BR};z-index:500;transition:right 0.35s cubic-bezier(0.4,0,0.2,1);overflow-y:auto;padding-bottom:3rem;}
.tp-menu-drawer.open{right:0;}
.tp-menu-head{padding:1.2rem 1.4rem;border-bottom:1px solid ${BR};display:flex;align-items:center;justify-content:space-between;}
.tp-menu-logo{font-family:'Barlow Condensed',sans-serif;font-weight:900;font-size:1.3rem;color:#fff;letter-spacing:0.05em;}
.tp-menu-logo span{color:${L};}
.tp-menu-close{font-size:1.3rem;color:#666;cursor:pointer;line-height:1;padding:4px;}
.tp-menu-close:hover{color:#fff;}
.tp-menu-section{padding:1.5rem 1.4rem 0.5rem;}
.tp-menu-section-label{font-family:'DM Mono',monospace;font-size:0.55rem;letter-spacing:0.22em;text-transform:uppercase;color:#444;margin-bottom:0.8rem;}
.tp-menu-item{display:flex;align-items:center;justify-content:space-between;padding:0.8rem 0;border-bottom:1px solid ${BR};cursor:pointer;transition:color 0.2s;}
.tp-menu-item:last-child{border-bottom:none;}
.tp-menu-item-label{font-family:'Barlow Condensed',sans-serif;font-weight:800;font-size:1.15rem;text-transform:uppercase;letter-spacing:0.05em;color:#e0e0e0;}
.tp-menu-item:hover .tp-menu-item-label{color:${L};}
.tp-menu-item-arrow{color:#444;font-size:0.8rem;transition:color 0.2s;}
.tp-menu-item:hover .tp-menu-item-arrow{color:${L};}
.tp-menu-sub{padding:0 0 0.5rem 1rem;border-bottom:1px solid ${BR};}
.tp-menu-sub-item{display:flex;align-items:center;gap:0.5rem;padding:0.6rem 0;cursor:pointer;transition:color 0.2s;}
.tp-menu-sub-item:hover .tp-menu-sub-label{color:${L};}
.tp-menu-sub-dot{width:5px;height:5px;border-radius:50%;background:${BR};flex-shrink:0;}
.tp-menu-sub-label{font-size:0.88rem;color:#777;transition:color 0.2s;}
.tp-menu-cta{margin:1.8rem 1.4rem 0;background:${L};color:#000;padding:0.95rem 1.2rem;font-family:'Barlow Condensed',sans-serif;font-weight:800;font-size:0.9rem;letter-spacing:0.1em;text-transform:uppercase;border:none;border-radius:2px;cursor:pointer;text-decoration:none;display:flex;align-items:center;justify-content:space-between;width:calc(100% - 2.8rem);}

/* PAGE HEADER */
.tp-page-hero{background:${CARD};border-bottom:1px solid ${BR};padding:2.2rem 1.3rem 1.8rem;}
.tp-page-back{display:flex;align-items:center;gap:0.4rem;font-family:'DM Mono',monospace;font-size:0.6rem;letter-spacing:0.15em;text-transform:uppercase;color:#555;cursor:pointer;margin-bottom:1.2rem;transition:color 0.2s;}
.tp-page-back:hover{color:${L};}
.tp-sec-tag{font-family:'DM Mono',monospace;font-size:0.6rem;letter-spacing:0.2em;text-transform:uppercase;color:${L};margin-bottom:0.35rem;}
.tp-page-title{font-family:'Barlow Condensed',sans-serif;font-weight:900;font-size:2.8rem;text-transform:uppercase;line-height:0.93;color:#fff;margin-bottom:0.8rem;}
.tp-page-desc{font-size:0.88rem;color:#666;line-height:1.7;}
.tp-accent-line{width:2.5rem;height:2.5px;background:${L};margin-top:0.7rem;}

/* SHARED */
.tp-section{padding:2rem 1.3rem;}
.tp-section.dark{background:${BG};}
.tp-section.surf{background:${SURF};}
.tp-section.card-bg{background:${CARD};}
.tp-sec-title{font-family:'Barlow Condensed',sans-serif;font-weight:900;font-size:1.5rem;text-transform:uppercase;letter-spacing:0.03em;color:#fff;margin-bottom:0.5rem;}
.tp-rule{height:1px;background:${BR};margin:1.2rem 0;}

/* SERVICE PACKAGES */
.tp-pkg-card{background:${BG};border:1px solid ${BR};border-radius:3px;padding:1.5rem 1.3rem;margin-bottom:1rem;position:relative;overflow:hidden;}
.tp-pkg-card::before{content:'';position:absolute;top:0;left:0;right:0;height:2px;background:${L};}
.tp-pkg-price{font-family:'Barlow Condensed',sans-serif;font-weight:900;font-size:2.5rem;color:${L};line-height:1;margin-bottom:0.15rem;}
.tp-pkg-name{font-family:'Barlow Condensed',sans-serif;font-weight:800;font-size:1.3rem;text-transform:uppercase;color:#fff;margin-bottom:1rem;}
.tp-pkg-list{list-style:none;display:flex;flex-direction:column;gap:0.55rem;margin-bottom:1.3rem;}
.tp-pkg-list li{display:flex;gap:0.6rem;font-size:0.8rem;color:#777;line-height:1.5;}
.tp-pkg-list li::before{content:'✓';color:${L};font-size:0.75rem;margin-top:0.05rem;flex-shrink:0;}
.tp-pkg-btn{display:flex;align-items:center;justify-content:space-between;background:${L};color:#000;padding:0.85rem 1.1rem;font-family:'Barlow Condensed',sans-serif;font-weight:800;font-size:0.85rem;letter-spacing:0.1em;text-transform:uppercase;border:none;border-radius:2px;cursor:pointer;text-decoration:none;width:100%;}
.tp-pkg-note{background:rgba(200,255,0,0.04);border:1px solid rgba(200,255,0,0.15);border-radius:3px;padding:0.9rem 1rem;font-family:'DM Mono',monospace;font-size:0.7rem;color:#666;letter-spacing:0.03em;line-height:1.6;margin-top:1rem;}
.tp-pkg-note strong{color:${L};}

/* FULL SERVICE SECTIONS */
.tp-fs-block{margin-bottom:2rem;}
.tp-fs-label{font-family:'DM Mono',monospace;font-size:0.6rem;letter-spacing:0.2em;text-transform:uppercase;color:${L};margin-bottom:0.6rem;display:flex;align-items:center;gap:0.5rem;}
.tp-fs-label::after{content:'';flex:1;height:1px;background:${BR};}
.tp-fs-heading{font-family:'Barlow Condensed',sans-serif;font-weight:800;font-size:1.15rem;text-transform:uppercase;color:#fff;margin-bottom:0.6rem;}
.tp-fs-list{list-style:none;display:flex;flex-direction:column;gap:0.45rem;}
.tp-fs-list li{display:flex;gap:0.6rem;font-size:0.8rem;color:#777;line-height:1.5;}
.tp-fs-list li::before{content:'—';color:${L};font-size:0.7rem;flex-shrink:0;}
.tp-fs-disclaimer{background:rgba(255,255,255,0.03);border:1px solid ${BR};border-radius:3px;padding:0.9rem 1rem;font-size:0.75rem;color:#555;line-height:1.65;margin-top:1.5rem;}
.tp-fs-disclaimer strong{color:#888;}

/* BIKE BUILD */
.tp-build-intro{font-size:0.88rem;color:#666;line-height:1.7;margin-bottom:1.5rem;}
.tp-build-heading{font-family:'Barlow Condensed',sans-serif;font-weight:900;font-size:1.6rem;text-transform:uppercase;color:${L};letter-spacing:0.05em;margin:0.5rem 0 0.8rem;border-left:3px solid ${L};padding-left:0.7rem;}
.tp-build-grid{display:grid;grid-template-columns:1fr 1fr;gap:3px;margin-bottom:2rem;}
.tp-build-cell{background:${CARD};aspect-ratio:1;overflow:hidden;}
.tp-build-cell img{width:100%;height:100%;object-fit:cover;opacity:0.82;display:block;}
.tp-build-cta-wrap{background:${CARD};border:1px solid ${BR};border-radius:3px;padding:1.3rem;margin-top:0.5rem;}
.tp-build-cta-title{font-family:'Barlow Condensed',sans-serif;font-weight:800;font-size:1.1rem;text-transform:uppercase;color:#fff;margin-bottom:0.5rem;}
.tp-build-cta-desc{font-size:0.8rem;color:#666;line-height:1.6;margin-bottom:1rem;}
.tp-btn-lime{display:flex;align-items:center;justify-content:space-between;background:${L};color:#000;padding:0.9rem 1.1rem;font-family:'Barlow Condensed',sans-serif;font-weight:800;font-size:0.85rem;letter-spacing:0.1em;text-transform:uppercase;border:none;border-radius:2px;cursor:pointer;text-decoration:none;width:100%;}
.tp-btn-dark{display:flex;align-items:center;justify-content:space-between;background:transparent;color:#f0f0f0;padding:0.9rem 1.1rem;font-family:'Barlow Condensed',sans-serif;font-weight:800;font-size:0.85rem;letter-spacing:0.1em;text-transform:uppercase;border:1px solid ${BR};border-radius:2px;cursor:pointer;text-decoration:none;width:100%;margin-top:0.6rem;}

/* WHEEL BUILD */
.tp-wheel-intro{font-size:0.88rem;color:#666;line-height:1.7;margin-bottom:1.5rem;}
.tp-wheel-factors{display:grid;grid-template-columns:1fr 1fr;gap:0.6rem;margin-bottom:1.5rem;}
.tp-wheel-factor{background:${BG};border:1px solid ${BR};border-radius:2px;padding:0.8rem;text-align:center;}
.tp-wheel-factor-icon{font-size:1.2rem;margin-bottom:0.3rem;}
.tp-wheel-factor-label{font-family:'DM Mono',monospace;font-size:0.62rem;letter-spacing:0.1em;text-transform:uppercase;color:#666;}
.tp-wheel-grid{display:grid;grid-template-columns:1fr 1fr;gap:3px;margin-bottom:1.5rem;}
.tp-wheel-cell{background:${CARD};aspect-ratio:1;overflow:hidden;}
.tp-wheel-cell img{width:100%;height:100%;object-fit:cover;opacity:0.82;display:block;}

/* TRAINING */
.tp-training-badge{background:${CARD};border:1px solid ${BR};border-radius:3px;padding:1.2rem;display:flex;align-items:center;gap:1rem;margin-bottom:1.5rem;}
.tp-training-badge-icon{font-size:2.5rem;flex-shrink:0;}
.tp-training-badge-name{font-family:'Barlow Condensed',sans-serif;font-weight:900;font-size:1.3rem;text-transform:uppercase;color:${L};line-height:1;}
.tp-training-badge-sub{font-size:0.75rem;color:#666;margin-top:0.2rem;}
.tp-training-intro{font-size:0.87rem;color:#666;line-height:1.7;margin-bottom:1.5rem;}
.tp-training-certs{display:flex;flex-direction:column;gap:0.5rem;margin-bottom:1.5rem;}
.tp-training-cert{display:flex;gap:0.7rem;align-items:flex-start;}
.tp-training-cert-dot{width:20px;height:20px;background:${L};border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:0.6rem;font-weight:700;color:#000;flex-shrink:0;margin-top:0.05rem;}
.tp-training-cert-txt{font-size:0.8rem;color:#888;line-height:1.55;}
.tp-training-highlight{background:rgba(200,255,0,0.04);border:1px solid rgba(200,255,0,0.18);border-radius:3px;padding:1.1rem;font-size:0.82rem;color:#aaa;line-height:1.65;margin-bottom:1.5rem;font-style:italic;}
.tp-training-links{display:flex;flex-direction:column;gap:0.6rem;}
.tp-training-link{display:flex;align-items:center;gap:0.7rem;font-family:'Barlow Condensed',sans-serif;font-weight:700;font-size:1rem;letter-spacing:0.06em;text-transform:uppercase;color:#f0f0f0;text-decoration:none;padding:0.8rem 1rem;border:1px solid ${BR};border-radius:2px;transition:border-color 0.2s,color 0.2s;}
.tp-training-link:hover{border-color:${L};color:${L};}

/* HOME */
.tp-hero{position:relative;min-height:520px;display:flex;flex-direction:column;justify-content:flex-end;padding:2rem 1.3rem 2rem;overflow:hidden;}
.tp-hero-bg{position:absolute;inset:0;background:#0a0a0a;}
.tp-hero-overlay{position:absolute;inset:0;background:linear-gradient(180deg,rgba(0,0,0,0.15) 0%,rgba(0,0,0,0.5) 45%,rgba(0,0,0,0.92) 100%);}
.tp-hero-content{position:relative;z-index:2;}
.tp-hero-h1{font-family:'Barlow Condensed',sans-serif;font-size:3.2rem;font-weight:900;line-height:0.92;text-transform:uppercase;margin-bottom:1rem;letter-spacing:0.01em;}
.tp-hero-h1 .wh{color:#fff;}
.tp-hero-h1 .gr{color:${L};font-style:italic;}
.tp-hero-desc{font-size:0.87rem;color:rgba(255,255,255,0.68);line-height:1.65;max-width:280px;margin-bottom:1.5rem;}
.tp-home-btn-lime{display:flex;align-items:center;justify-content:space-between;background:${L};color:#000;padding:0.95rem 1.2rem;font-family:'Barlow Condensed',sans-serif;font-weight:800;font-size:0.88rem;letter-spacing:0.12em;text-transform:uppercase;border:none;border-radius:2px;cursor:pointer;text-decoration:none;width:100%;margin-bottom:0.7rem;}
.tp-home-btn-dark{display:flex;align-items:center;justify-content:space-between;background:rgba(255,255,255,0.05);color:#fff;padding:0.95rem 1.2rem;font-family:'Barlow Condensed',sans-serif;font-weight:800;font-size:0.88rem;letter-spacing:0.12em;text-transform:uppercase;border:1px solid rgba(255,255,255,0.18);border-radius:2px;cursor:pointer;text-decoration:none;width:100%;}
.tp-trust{background:${CARD};padding:2rem 1.3rem;border-bottom:1px solid ${BR};}
.tp-trust-tag{font-family:'DM Mono',monospace;font-size:0.6rem;letter-spacing:0.2em;text-transform:uppercase;color:${L};margin-bottom:0.4rem;}
.tp-trust-title{font-family:'Barlow Condensed',sans-serif;font-weight:900;font-size:2rem;text-transform:uppercase;line-height:0.95;color:#fff;margin-bottom:1.4rem;}
.tp-trust-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:0.5rem;margin-bottom:1.4rem;}
.tp-ts{text-align:center;}
.tp-ts-icon{font-size:1.3rem;color:${L};margin-bottom:0.3rem;}
.tp-ts-num{font-family:'Barlow Condensed',sans-serif;font-weight:900;font-size:1.2rem;color:#fff;line-height:1;}
.tp-ts-lbl{font-family:'DM Mono',monospace;font-size:0.52rem;letter-spacing:0.1em;text-transform:uppercase;color:#555;line-height:1.4;}
.tp-divider{height:1px;background:${BR};margin:1.1rem 0;}
.tp-review{display:flex;align-items:center;gap:0.8rem;margin-bottom:0.75rem;}
.tp-review-stars{color:${L};font-size:0.75rem;}
.tp-review-info{font-size:0.7rem;color:#555;font-family:'DM Mono',monospace;letter-spacing:0.04em;}
.tp-review-score{font-family:'Barlow Condensed',sans-serif;font-weight:900;font-size:1.05rem;color:#fff;margin-right:0.25rem;}

/* SERVICES HOME SECTION */
.tp-home-services{background:${BG};padding:2rem 0 1.5rem;}
.tp-home-services-hdr{padding:0 1.3rem;margin-bottom:1.5rem;}
.tp-sec-title-lg{font-family:'Barlow Condensed',sans-serif;font-weight:900;font-size:2.3rem;text-transform:uppercase;line-height:0.95;color:#fff;margin-bottom:0.5rem;}
.tp-svc-card{background:${CARD};border:1px solid ${BR};margin:0 1.3rem 1rem;border-radius:2px;overflow:hidden;cursor:pointer;}
.tp-svc-img{width:100%;height:180px;background:linear-gradient(135deg,#1a1a18,#252520);position:relative;overflow:hidden;}
.tp-svc-img img{width:100%;height:100%;object-fit:cover;opacity:0.75;display:block;}
.tp-svc-num-tag{position:absolute;top:0.7rem;right:0.8rem;font-family:'Barlow Condensed',sans-serif;font-weight:900;font-size:0.85rem;color:rgba(255,255,255,0.2);letter-spacing:0.05em;}
.tp-svc-badge-icon{position:absolute;bottom:0.75rem;left:0.75rem;width:34px;height:34px;background:${L};display:flex;align-items:center;justify-content:center;font-size:0.95rem;border-radius:2px;}
.tp-svc-body{padding:1rem 1rem 1rem;}
.tp-svc-num-lbl{font-family:'DM Mono',monospace;font-size:0.58rem;letter-spacing:0.14em;text-transform:uppercase;color:#444;margin-bottom:0.4rem;}
.tp-svc-name{font-family:'Barlow Condensed',sans-serif;font-weight:900;font-size:1.4rem;text-transform:uppercase;color:#fff;line-height:1.0;margin-bottom:0.45rem;}
.tp-svc-desc{font-size:0.8rem;color:#666;line-height:1.6;margin-bottom:0.85rem;}
.tp-svc-link{font-family:'Barlow Condensed',sans-serif;font-weight:700;font-size:0.82rem;letter-spacing:0.1em;text-transform:uppercase;color:${L};display:flex;align-items:center;gap:0.4rem;}
.tp-dots{display:flex;justify-content:center;gap:0.4rem;padding:0.5rem 0 0.2rem;}
.tp-dot-on{width:18px;height:6px;background:${L};border-radius:3px;}
.tp-dot-off{width:6px;height:6px;background:#2a2a2a;border-radius:50%;cursor:pointer;}

/* PROCESS */
.tp-process{background:${SURF};padding:2.5rem 1.3rem;}
.tp-process-title{font-family:'Barlow Condensed',sans-serif;font-weight:900;font-size:2.8rem;text-transform:uppercase;line-height:0.92;color:#fff;margin:0.4rem 0 0.8rem;}
.tp-steps{margin-top:1.8rem;position:relative;}
.tp-steps-line{position:absolute;left:1.1rem;top:1.8rem;bottom:1.8rem;width:1.5px;background:repeating-linear-gradient(to bottom,${L} 0,${L} 6px,transparent 6px,transparent 12px);}
.tp-step{display:flex;gap:1.1rem;margin-bottom:1.8rem;position:relative;}
.tp-step-icon{width:34px;height:34px;flex-shrink:0;display:flex;align-items:center;justify-content:center;background:${BG};border:1.5px solid ${BR};border-radius:50%;font-size:0.95rem;z-index:1;}
.tp-step-num{font-family:'DM Mono',monospace;font-size:0.55rem;letter-spacing:0.15em;color:${L};margin-bottom:0.22rem;}
.tp-step-title{font-family:'Barlow Condensed',sans-serif;font-weight:800;font-size:1.1rem;text-transform:uppercase;color:#fff;line-height:1.1;margin-bottom:0.25rem;}
.tp-step-desc{font-size:0.79rem;color:#666;line-height:1.6;}

/* CTA */
.tp-cta{background:${L};padding:2.2rem 1.3rem;}
.tp-cta-eye{font-family:'DM Mono',monospace;font-size:0.58rem;letter-spacing:0.2em;text-transform:uppercase;color:rgba(0,0,0,0.55);margin-bottom:0.35rem;}
.tp-cta-title{font-family:'Barlow Condensed',sans-serif;font-weight:900;font-size:2.1rem;text-transform:uppercase;line-height:0.95;color:#000;margin-bottom:1.4rem;}
.tp-cta-btn{display:flex;align-items:center;justify-content:center;gap:0.6rem;background:#000;color:#fff;padding:1rem 1.2rem;font-family:'Barlow Condensed',sans-serif;font-weight:800;font-size:0.87rem;letter-spacing:0.1em;text-transform:uppercase;border:none;border-radius:2px;cursor:pointer;text-decoration:none;width:100%;margin-bottom:1rem;}
.tp-cta-alt-lbl{font-family:'DM Mono',monospace;font-size:0.58rem;letter-spacing:0.2em;text-transform:uppercase;color:rgba(0,0,0,0.38);display:block;text-align:center;margin-bottom:0.35rem;}
.tp-cta-alt-link{font-family:'Barlow Condensed',sans-serif;font-weight:800;font-size:0.87rem;letter-spacing:0.12em;text-transform:uppercase;color:#000;text-decoration:none;display:block;text-align:center;}

/* BUILDS */
.tp-builds{background:${BG};padding:2rem 1.3rem;}
.tp-builds-grid{display:grid;grid-template-columns:1fr 1fr;grid-template-rows:repeat(3,110px);gap:3px;margin:1.1rem 0 0.8rem;}
.tp-build-cell2{background:${CARD};overflow:hidden;}
.tp-builds-link{font-family:'Barlow Condensed',sans-serif;font-weight:700;font-size:0.85rem;letter-spacing:0.12em;text-transform:uppercase;color:${L};display:flex;align-items:center;gap:0.4rem;cursor:pointer;}

/* TESTIMONIALS */
.tp-test{background:${SURF};padding:2rem 1.3rem;}
.tp-test-quote{font-family:'Barlow Condensed',sans-serif;font-weight:900;font-size:4rem;color:${L};line-height:0.7;margin-bottom:1.2rem;}
.tp-test-card{background:${CARD};border:1px solid ${BR};border-radius:3px;padding:1.2rem;}
.tp-test-text{font-size:0.88rem;color:#ccc;line-height:1.65;margin-bottom:1.1rem;}
.tp-test-author{display:flex;align-items:center;gap:0.75rem;}
.tp-test-ava{width:38px;height:38px;border-radius:50%;background:linear-gradient(135deg,#2a2a2a,#333);border:1.5px solid ${BR};display:flex;align-items:center;justify-content:center;font-size:1.1rem;flex-shrink:0;}
.tp-test-name{font-family:'Barlow Condensed',sans-serif;font-weight:800;font-size:0.95rem;text-transform:uppercase;color:#fff;line-height:1.1;}
.tp-test-role{font-family:'DM Mono',monospace;font-size:0.56rem;letter-spacing:0.14em;text-transform:uppercase;color:#555;}

/* INSTAGRAM */
.tp-insta{background:${BG};padding:2rem 1.3rem;}
.tp-insta-handle{font-family:'Barlow Condensed',sans-serif;font-weight:900;font-size:1.9rem;text-transform:uppercase;color:#fff;margin:0.2rem 0 1.1rem;}
.tp-insta-grid{display:grid;grid-template-columns:repeat(3,1fr);grid-template-rows:repeat(2,100px);gap:3px;margin-bottom:1rem;}
.tp-insta-cell{background:${CARD};overflow:hidden;}
.tp-insta-btn{display:flex;align-items:center;justify-content:center;gap:0.5rem;background:transparent;color:#fff;padding:0.9rem 1.2rem;font-family:'Barlow Condensed',sans-serif;font-weight:800;font-size:0.82rem;letter-spacing:0.12em;text-transform:uppercase;border:1px solid ${BR};border-radius:2px;cursor:pointer;text-decoration:none;width:100%;}

/* FOOTER */
.tp-footer{background:${CARD};border-top:1px solid ${BR};padding:2rem 1.3rem 1.5rem;}
.tp-footer-logo{font-family:'Barlow Condensed',sans-serif;font-weight:900;font-size:1.65rem;letter-spacing:0.05em;color:#fff;line-height:1;}
.tp-footer-logo span{color:${L};}
.tp-footer-sub{font-family:'DM Mono',monospace;font-size:0.46rem;letter-spacing:0.2em;text-transform:uppercase;color:#444;margin-bottom:0.6rem;}
.tp-footer-tag{font-size:0.79rem;color:#555;line-height:1.65;max-width:250px;margin-bottom:1.2rem;}
.tp-footer-socials{display:flex;gap:0.75rem;margin-bottom:1.7rem;}
.tp-footer-social{width:32px;height:32px;border:1px solid ${BR};border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:0.85rem;cursor:pointer;text-decoration:none;}
.tp-footer-cols{display:grid;grid-template-columns:1fr 1fr;gap:1.3rem;margin-bottom:1.5rem;}
.tp-footer-col-ttl{font-family:'Barlow Condensed',sans-serif;font-weight:800;font-size:0.95rem;text-transform:uppercase;letter-spacing:0.08em;color:#fff;margin-bottom:0.75rem;}
.tp-footer-menu{list-style:none;display:flex;flex-direction:column;gap:0.5rem;}
.tp-footer-menu a{font-size:0.81rem;color:#666;text-decoration:none;cursor:pointer;}
.tp-footer-menu a:hover{color:${L};}
.tp-footer-crow{display:flex;align-items:flex-start;gap:0.45rem;margin-bottom:0.55rem;}
.tp-footer-cicon{color:${L};font-size:0.77rem;flex-shrink:0;margin-top:0.1rem;}
.tp-footer-ctxt{font-size:0.75rem;color:#666;line-height:1.5;}
.tp-footer-copy{border-top:1px solid ${BR};padding-top:1.1rem;font-family:'DM Mono',monospace;font-size:0.58rem;letter-spacing:0.07em;color:#333;text-align:center;}

/* MARQUEE */
.tp-marquee{border-top:1px solid ${BR};border-bottom:1px solid ${BR};padding:0.8rem 0;overflow:hidden;background:${SURF};}
.tp-mtrack{display:flex;gap:2rem;animation:tpM 30s linear infinite;width:max-content;}
@keyframes tpM{from{transform:translateX(0)}to{transform:translateX(-50%)}}
.tp-mitem{font-family:'Barlow Condensed',sans-serif;font-size:0.78rem;letter-spacing:0.18em;text-transform:uppercase;color:#3a3a3a;white-space:nowrap;display:flex;align-items:center;gap:2rem;}
.tp-mitem .dot{color:${L};font-size:0.5rem;}
@keyframes tpPulse{0%,100%{box-shadow:0 0 0 0 rgba(200,255,0,0.4)}50%{box-shadow:0 0 0 6px rgba(200,255,0,0)}}
`;

